window.kbPageData["views/entry/k-05e868a7fd828ea3"] = {"key":"entry/k-05e868a7fd828ea3","state":{"route":"entry/k-05e868a7fd828ea3"},"node":{"id":"k-05e868a7fd828ea3","mode":"k","title":"公共场所采集的个人图像与身份识别信息用途限制","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["公共场所采集的个人图像和身份识别信息的用途限制及单独同意例外"],"qs":["国考 2023 行政执法 行测#11"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"《个人信息保护法》第二十六条规定，在公共场所安装图像采集、个人身份识别设备，应当为维护公共安全所必需，遵守国家有关规定，并设置显著的提示标识。依此收集的个人图像和身份识别信息原则上只能用于维护公共安全，取得个人单独同意的，可以用于其他目的。","review":{"definition":"《个人信息保护法》第二十六条规定，在公共场所安装图像采集、个人身份识别设备，应当为维护公共安全所必需，遵守国家有关规定，并设置显著的提示标识。依此收集的个人图像和身份识别信息原则上只能用于维护公共安全，取得个人单独同意的，可以用于其他目的。","explanation":"该条约束的是公共场所安装相关设备及其所采集信息的用途。B项把限制泛化为经人脸识别技术收集的信息一律只能用于公共安全，并遗漏个人单独同意的例外，因此是本题要求选出的不符合法律规定的说法。","references":[],"evidence":"只能用于维护公共安全的目的，不得用于其他目的；取得个人单独同意的除外。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 行政执法 行测#11":{"paper":"国考 2023 行政执法 行测","n":11,"mod":"常识判断","src":["857378cf496f27296500.pdf",2],"asrc":["d23139fe5a0fb3115135.pdf",5],"card":"811be8dab9eb627b655084bc","links":[{"id":"k-05e868a7fd828ea3","role":"直接考查","why":"能否将相关信息用于其他目的取决于是否取得个人单独同意。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-05e868a7fd828ea3":[["国考 2023 行政执法 行测#11"]]}};
